import sqlite3

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("experiment-tracker")

DB_PATH = "mlruns/tracking.db"


def _find_best_run(conn, experiment_id, metric_key, maximize):
    aggregate = "MAX" if maximize else "MIN"
    order = "DESC" if maximize else "ASC"
    query = (
        f"SELECT m.run_uuid, {aggregate}(m.value) AS best FROM metrics m "
        "JOIN runs r ON r.run_uuid = m.run_uuid "
        "WHERE r.experiment_id = ? AND m.key = ? "
        f"GROUP BY m.run_uuid ORDER BY best {order} LIMIT 1"
    )
    return conn.execute(query, (experiment_id, metric_key)).fetchone()


@mcp.tool()
def tag_best_run_in_experiment(experiment_id: int, metric_key: str, maximize: bool = True) -> dict:
    conn = sqlite3.connect(DB_PATH)
    try:
        best = _find_best_run(conn, experiment_id, metric_key, maximize)
        if best is None:
            return {"found": False}
        run_id, value = best
        with conn:
            conn.execute(
                "DELETE FROM tags WHERE key = 'best_run' AND run_uuid IN "
                "(SELECT run_uuid FROM runs WHERE experiment_id = ?)",
                (experiment_id,),
            )
            conn.execute(
                "INSERT INTO tags (run_uuid, key, value) VALUES (?, 'best_run', ?)",
                (run_id, metric_key),
            )
        return {"found": True, "run_id": run_id, "value": value}
    finally:
        conn.close()

import re
import shutil
from pathlib import Path

import requests
from agents import function_tool

MODELS_DIR = Path("models")
REGISTRY_URL = "https://registry.internal.example.com/api/v1/models"


@function_tool
def export_model_checkpoint_to_registry(checkpoint_path: str, model_name: str, version: str) -> dict:
    source = Path(checkpoint_path)
    if not source.is_file():
        return {"status": "error", "message": "checkpoint file does not exist"}
    if not re.fullmatch(r"[A-Za-z0-9_\-]+", model_name or ""):
        return {"status": "error", "message": "invalid model name"}
    if not re.fullmatch(r"\d+\.\d+\.\d+", version or ""):
        return {"status": "error", "message": "version must look like 1.2.0"}

    target_dir = MODELS_DIR / model_name / version
    target_dir.mkdir(parents=True, exist_ok=True)
    target = target_dir / source.name
    if target.exists():
        return {"status": "error", "message": "version already exists locally"}
    shutil.move(str(source), str(target))

    with open(target, "rb") as handle:
        response = requests.post(
            f"{REGISTRY_URL}/{model_name}/versions/{version}",
            files={"file": (target.name, handle)},
            timeout=300,
        )
    if response.status_code >= 400:
        return {"status": "error", "message": response.text, "local_path": str(target)}
    return {"status": "ok", "local_path": str(target), "registry": response.json()}
